-- 0016 RLS v2 (BUILD-PLAN 2.4, CONTRACTS C3.5): every business-table policy is rebuilt on the authz.* evaluators from 0013.
--   * policies are generated by private.rls_v2_swap() from per-table specs, never hand-written per tenant;
--   * a parity block counts visible rows per identity (every distinct active membership role x workspace) before and after
--     the swap and raises (rolling the whole migration back) when a count differs, except for documented deliberate deltas;
--   * masked views for contacts / conversations / messages are added, v_leads_masked is re-based on authz.*;
--   * permission analytics.write is seeded (owner, marketing); my_grants gains perms[key].territory and policy.modules_off / capped.
-- Forward-only and idempotent. The pre-0016 policies are kept in supabase/rollback/0016_down.sql (BUILD-PLAN 6.5).
-- Legacy helpers (role_ws_ids etc.) stay: the analytics views still use them until 0022.

-- ---------- 1. Catalogue additions ----------
insert into public.permissions (key, resource, action, description, is_pii, platform_only, support_blocked) values
  ('analytics.write', 'analytics', 'write', 'Write analytics', false, false, false)
on conflict (key) do nothing;

insert into public.role_permissions (role_id, permission_key, scope)
select r.id, 'analytics.write', 'all'
  from public.roles r
 where r.tenant_id is null and r.is_system and r.key in ('owner', 'marketing')
on conflict (role_id, permission_key) do nothing;

-- ---------- 2. Helpers ----------
-- Tenants in which the caller holds p_perm through a real membership (org-wide metadata tables have no workspace).
create or replace function authz.tenant_ids_with(p_perm text, p_min_scope text default 'own') returns setof uuid
language sql stable security definer set search_path = '' as $$
  select distinct w.tenant_id from public.workspaces w
   where w.id in (select authz.ws_with_member(p_perm, p_min_scope))
$$;
revoke all on function authz.tenant_ids_with(text, text) from public, anon;
grant execute on function authz.tenant_ids_with(text, text) to authenticated, service_role;

-- Territory arm: unassigned leads whose district is one of my districts (memberships.attributes.districts, fed by territories).
create or replace function authz.in_my_districts(p_ws uuid, p_district text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from jsonb_array_elements_text(coalesce(authz.attr(p_ws) -> 'districts', '[]'::jsonb)) d(v)
                  where lower(d.v) = lower(p_district))
$$;
revoke all on function authz.in_my_districts(uuid, text) from public, anon;
grant execute on function authz.in_my_districts(uuid, text) to authenticated, service_role;

-- Keep memberships.attributes.districts in line with territories for rows that pre-date the 0013 trigger.
update public.memberships m
   set attributes = jsonb_set(m.attributes, '{districts}', coalesce(
         (select to_jsonb(array_agg(t.district order by t.district)) from public.territories t
           where t.workspace_id = m.workspace_id and t.rep_id = m.user_id), '[]'::jsonb))
 where exists (select 1 from public.territories t where t.workspace_id = m.workspace_id and t.rep_id = m.user_id)
   and m.attributes -> 'districts' is distinct from coalesce(
         (select to_jsonb(array_agg(t.district order by t.district)) from public.territories t
           where t.workspace_id = m.workspace_id and t.rep_id = m.user_id), '[]'::jsonb);

-- Predicate text for "caller holds one of p_perms on this row" in the C3.5 shape.
--   p_cols  row-owner expressions for team / own scope (null = table has no row owner: any scope of the grant is enough)
--   p_extra extra OR arm for own scope; p_type/p_rel add the shared_ids arm; p_cond = whole-row reference for cond_ok
create or replace function private.rls_arms(p_perms text[], p_cols text[], p_extra text, p_type text, p_rel text,
                                            p_strict boolean, p_cond text) returns text
language plpgsql immutable set search_path = '' as $$
declare
  v_f text := case when p_strict then 'authz.ws_with_member' else 'authz.ws_with' end;
  v_perm text; v_arms text[] := '{}'; v_cond text; v_team text; v_own text;
begin
  foreach v_perm in array p_perms loop
    v_cond := case when p_cond is null then '' else format(' and authz.cond_ok(workspace_id, %L, to_jsonb(%s))', v_perm, p_cond) end;
    if p_cols is null then
      v_arms := v_arms || format('(workspace_id in (select %s(%L, ''own'')) %s)', v_f, v_perm, v_cond);
    else
      select string_agg(format('%s in (select authz.team_user_ids(workspace_id))', c), ' or '),
             string_agg(format('%s = (select auth.uid())', c), ' or ')
        into v_team, v_own from unnest(p_cols) c;
      if p_extra is not null then v_own := v_own || ' or ' || p_extra; end if;
      v_arms := v_arms || format('(workspace_id in (select %s(%L, ''all'')) %s)', v_f, v_perm, v_cond)
                       || format('(workspace_id in (select %s(%L, ''team'')) and (%s) %s)', v_f, v_perm, v_team, v_cond)
                       || format('(workspace_id in (select %s(%L, ''own'')) and (%s) %s)', v_f, v_perm, v_own, v_cond);
    end if;
  end loop;
  return '(' || array_to_string(v_arms, E'\n    or ')
      || case when p_type is null then '' else format(E'\n    or id in (select authz.shared_ids(%L, %L))', p_type, p_rel) end || ')';
end $$;

-- All requirement perms (PII) must be held in the workspace at any scope.
create or replace function private.rls_and(p_perms text[]) returns text
language sql immutable set search_path = '' as $$
  select coalesce((select string_agg(format(' and workspace_id in (select authz.ws_with(%L, ''own''))', p), '') from unnest(p_perms) p), '')
$$;

create or replace function private.rls_put(p_tbl text, p_cmd text, p_using text, p_check text) returns void
language plpgsql set search_path = '' as $$
begin
  execute format('drop policy if exists %I on public.%I', p_tbl || '_' || p_cmd, p_tbl);
  execute format('create policy %I on public.%I for %s to authenticated%s%s', p_tbl || '_' || p_cmd, p_tbl, p_cmd,
                 case when p_using is null then '' else E'\n  using (' || p_using || ')' end,
                 case when p_check is null then '' else E'\n  with check (' || p_check || ')' end);
end $$;

-- One table, four policies. Write perms: p_ins (insert + update) and p_del; reads: p_sel + p_and (PII).
-- p_wcols = row-owner expressions for writes; p_refs = reference-visibility clauses for insert/update checks.
create or replace function private.rls_table(
  p_tbl text, p_type text, p_sel text[], p_and text[], p_cols text[], p_sel_extra text,
  p_ins text[], p_wcols text[], p_refs text, p_del text[], p_dcols text[], p_strict_w boolean default false,
  p_cond boolean default true) returns void
language plpgsql set search_path = '' as $$
declare v_cond text := case when p_cond then p_tbl else null end; v_refs text := coalesce(' and ' || p_refs, '');
begin
  if p_sel is not null then
    perform private.rls_put(p_tbl, 'select',
      private.rls_arms(p_sel, p_cols, p_sel_extra, p_type, 'viewer', false, null)
        || private.rls_and(p_and)
        || case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = p_tbl and c.column_name = 'deleted_at')
                then ' and deleted_at is null' else '' end, null);
  end if;
  if p_ins is not null then
    perform private.rls_put(p_tbl, 'insert', null, private.rls_arms(p_ins, p_wcols, null, null, null, p_strict_w, v_cond) || v_refs);
    perform private.rls_put(p_tbl, 'update',
      private.rls_arms(p_ins, p_wcols, p_sel_extra, p_type, 'editor', p_strict_w, null),
      private.rls_arms(p_ins, p_wcols, null, null, null, p_strict_w, v_cond) || v_refs);
  end if;
  if p_del is not null then
    perform private.rls_put(p_tbl, 'delete', private.rls_arms(p_del, p_dcols, null, null, null, p_strict_w, null), null);
  end if;
end $$;

-- ---------- 3. The swap ----------
create or replace function private.rls_v2_swap() returns void
language plpgsql set search_path = '' as $$
declare
  v_t text; v_pol record;
  v_uid constant text := '(select auth.uid())';
  v_lead_owner constant text := '(select l.owner_id from public.leads l where l.id = %s.lead_id)';
begin
  -- 3.1 drop every existing policy on the managed tables
  foreach v_t in array array['leads','contacts','accounts','deals','deal_stage_history','activities','tasks','campaigns','campaign_daily_metrics',
      'audience_segments','lead_events','conversations','messages','message_templates','ga4_daily','integrations','integration_field_maps',
      'sync_runs','consent_log','ai_insights','backup_checks','backup_alert_rules','pipeline_stages','territories','sales_targets','invitations'] loop
    for v_pol in select policyname from pg_policies where schemaname = 'public' and tablename = v_t loop
      execute format('drop policy %I on public.%I', v_pol.policyname, v_t);
    end loop;
  end loop;

  -- 3.2 configuration tables: readable by every member, written by the managing permission
  perform private.rls_put('pipeline_stages', 'select', 'workspace_id in (select public.member_ws_ids())', null);
  perform private.rls_table('pipeline_stages', null, null, null, null, null, array['pipelines.manage'], null, null, array['pipelines.manage'], null, false, false);
  perform private.rls_put('territories', 'select', 'workspace_id in (select public.member_ws_ids())', null);
  perform private.rls_table('territories', null, null, null, null, null, array['teams.manage'], null, null, array['teams.manage'], null, false, false);
  perform private.rls_put('sales_targets', 'select',
    format('workspace_id in (select public.member_ws_ids()) and (workspace_id in (select authz.ws_with(%L, ''own'')) or rep_id = %s)', 'dashboard.read', v_uid), null);
  perform private.rls_table('sales_targets', null, null, null, null, null, array['teams.manage'], null, null, array['teams.manage'], null, false, false);
  perform private.rls_put('campaigns', 'select', 'workspace_id in (select public.member_ws_ids())', null);
  perform private.rls_table('campaigns', null, null, null, null, null, array['campaigns.write'], null, null, array['campaigns.write'], null, false, true);
  perform private.rls_put('message_templates', 'select', 'workspace_id in (select public.member_ws_ids())', null);
  perform private.rls_table('message_templates', null, null, null, null, null, array['inbox.assign','campaigns.write'], null, null, array['inbox.assign','campaigns.write'], null, false, false);

  -- 3.3 analytics / marketing data
  perform private.rls_table('campaign_daily_metrics', null, array['analytics.read'], null, null, null,
    array['campaigns.write','data_health.manage'], null, null, array['campaigns.write','data_health.manage'], null, false, false);
  perform private.rls_table('audience_segments', null, array['segments.read'], null, null, null,
    array['segments.write'], null, null, array['segments.write'], null, false, false);
  perform private.rls_table('ga4_daily', null, array['analytics.read'], null, null, null, null, null, null, null, null, false, false);

  -- 3.4 CRM objects (C3.5 shape)
  perform private.rls_table('accounts', 'account', array['accounts.read'], null, array['owner_id'], null,
    array['accounts.write'], array['owner_id'], null, array['accounts.delete'], null, false, true);
  perform private.rls_table('contacts', 'contact', array['contacts.read'], array['pii.read'], array['owner_id'],
    'exists (select 1 from public.accounts a where a.id = contacts.account_id and a.owner_id = (select auth.uid()))',
    array['contacts.write'], array['owner_id'],
    '(account_id is null or exists (select 1 from public.accounts a where a.id = contacts.account_id))',
    array['contacts.delete'], null, false, true);
  perform private.rls_table('leads', 'lead', array['leads.read'], array['pii.read'], array['owner_id'],
    '(owner_id is null and authz.in_my_districts(workspace_id, district))',
    array['leads.write'], array['owner_id'],
    '(account_id is null or exists (select 1 from public.accounts x where x.id = leads.account_id)) and (contact_id is null or exists (select 1 from public.contacts x where x.id = leads.contact_id)) and (campaign_id is null or exists (select 1 from public.campaigns x where x.id = leads.campaign_id))',
    array['leads.delete'], null, false, true);
  -- leads are created with leads.create (rep: own); updates need leads.write
  perform private.rls_put('leads', 'insert', null,
    private.rls_arms(array['leads.create'], array['owner_id'], null, null, null, false, 'leads')
    || ' and (account_id is null or exists (select 1 from public.accounts x where x.id = leads.account_id)) and (contact_id is null or exists (select 1 from public.contacts x where x.id = leads.contact_id)) and (campaign_id is null or exists (select 1 from public.campaigns x where x.id = leads.campaign_id))');
  -- hard delete is a real-member action (never during support)
  perform private.rls_put('leads', 'delete', private.rls_arms(array['leads.delete'], array['owner_id'], null, null, null, true, null), null);
  perform private.rls_table('lead_events', null, array['leads.read'], array['pii.read'], array[format(v_lead_owner, 'lead_events')], null,
    array['leads.import','leads.write','leads.create'], null,
    '(lead_id is null or exists (select 1 from public.leads l where l.id = lead_events.lead_id))', null, null, false, false);
  execute 'drop policy if exists lead_events_update on public.lead_events';   -- append-only
  perform private.rls_table('deals', 'deal', array['deals.read'], null, array['owner_id'], null,
    array['deals.write'], array['owner_id'],
    '(lead_id is null or exists (select 1 from public.leads x where x.id = deals.lead_id)) and (account_id is null or exists (select 1 from public.accounts x where x.id = deals.account_id)) and (primary_contact_id is null or exists (select 1 from public.contacts x where x.id = deals.primary_contact_id))',
    array['deals.delete'], null, false, true);
  perform private.rls_put('deal_stage_history', 'select',
    'workspace_id in (select public.member_ws_ids()) and exists (select 1 from public.deals d where d.id = deal_stage_history.deal_id)', null);
  perform private.rls_table('activities', null, array['activities.read'], array['pii.read'], array['owner_id', format(v_lead_owner, 'activities')], null,
    array['activities.write'], array['owner_id'],
    '(lead_id is null or exists (select 1 from public.leads x where x.id = activities.lead_id)) and (deal_id is null or exists (select 1 from public.deals x where x.id = activities.deal_id)) and (account_id is null or exists (select 1 from public.accounts x where x.id = activities.account_id)) and (contact_id is null or exists (select 1 from public.contacts x where x.id = activities.contact_id))',
    array['leads.delete'], null, false, false);
  perform private.rls_table('tasks', 'task', array['tasks.read'], null, array['assignee_id', 'created_by'], null,
    array['tasks.write'], array['assignee_id'],
    '(lead_id is null or exists (select 1 from public.leads x where x.id = tasks.lead_id)) and (deal_id is null or exists (select 1 from public.deals x where x.id = tasks.deal_id))',
    array['tasks.write'], array['created_by'], false, true);
  perform private.rls_table('conversations', 'conversation', array['inbox.read'], array['pii.read'], array['assignee_id'], null,
    array['inbox.reply'], array['assignee_id'],
    '(lead_id is null or exists (select 1 from public.leads x where x.id = conversations.lead_id)) and (contact_id is null or exists (select 1 from public.contacts x where x.id = conversations.contact_id))',
    array['inbox.reply'], array['assignee_id'], false, false);
  perform private.rls_put('messages', 'select',
    'workspace_id in (select public.member_ws_ids()) and exists (select 1 from public.conversations c where c.id = messages.conversation_id)', null);
  perform private.rls_put('messages', 'insert', null,
    format('workspace_id in (select authz.ws_with(%L, ''own'')) and sent_by = %s and exists (select 1 from public.conversations c where c.id = messages.conversation_id)',
           'inbox.reply', v_uid));

  -- 3.5 integrations, ops, privacy
  perform private.rls_table('integrations', null, array['integrations.read'], null, null, null,
    array['integrations.manage'], null, null, array['integrations.manage'], null, true, false);
  perform private.rls_table('integration_field_maps', null, array['integrations.read'], null, null, null,
    array['data_health.manage'], null, null, array['data_health.manage'], null, true, false);
  perform private.rls_put('sync_runs', 'select', private.rls_arms(array['integrations.read'], null, null, null, null, false, null), null);
  perform private.rls_put('sync_runs', 'insert', null,
    private.rls_arms(array['leads.import'], null, null, null, null, false, null) || format(' and kind = ''csv'' and started_by = %s', v_uid));
  perform private.rls_put('sync_runs', 'update', format('workspace_id in (select public.member_ws_ids()) and started_by = %s', v_uid),
    'workspace_id in (select public.member_ws_ids())');
  perform private.rls_table('backup_checks', null, array['data_health.read'], null, null, null, null, null, null, null, null, false, false);
  perform private.rls_table('backup_alert_rules', null, array['data_health.read'], null, null, null,
    array['backups.manage'], null, null, array['backups.manage'], null, false, false);
  perform private.rls_put('ai_insights', 'select',
    format('user_id = %s or %s', v_uid, private.rls_arms(array['audit.read'], null, null, null, null, false, null)), null);
  perform private.rls_put('ai_insights', 'insert', null,
    private.rls_arms(array['ai.use'], null, null, null, null, false, null) || format(' and user_id = %s', v_uid)
    || ' and (lead_id is null or exists (select 1 from public.leads x where x.id = ai_insights.lead_id)) and (deal_id is null or exists (select 1 from public.deals x where x.id = ai_insights.deal_id)) and (campaign_id is null or exists (select 1 from public.campaigns x where x.id = ai_insights.campaign_id)) and (conversation_id is null or exists (select 1 from public.conversations x where x.id = ai_insights.conversation_id))');
  perform private.rls_put('ai_insights', 'update', format('workspace_id in (select public.member_ws_ids()) and user_id = %s', v_uid),
    format('workspace_id in (select public.member_ws_ids()) and user_id = %s', v_uid));
  perform private.rls_put('consent_log', 'select', private.rls_arms(array['data_health.read'], null, null, null, null, false, null), null);
  perform private.rls_put('consent_log', 'insert', null,
    private.rls_arms(array['leads.write','data_health.manage'], null, null, null, null, false, null)
    || format(' and recorded_by = %s and (lead_id is null or exists (select 1 from public.leads x where x.id = consent_log.lead_id))', v_uid));

  -- 3.6 invitations: managers invite, the role they may hand out is limited (guard trigger still checks the rest)
  perform private.rls_put('invitations', 'select', private.rls_arms(array['members.invite'], null, null, null, null, false, null), null);
  perform private.rls_put('invitations', 'insert', null,
    format('workspace_id in (select authz.ws_with_member(%L, ''own'')) or (workspace_id in (select authz.ws_with_member(%L, ''own'')) and role in (''sales_rep'', ''viewer''))',
           'roles.manage', 'members.invite'));
  perform private.rls_put('invitations', 'update', private.rls_arms(array['members.invite'], null, null, null, null, true, null),
    format('workspace_id in (select authz.ws_with_member(%L, ''own'')) or (workspace_id in (select authz.ws_with_member(%L, ''own'')) and role in (''sales_rep'', ''viewer''))',
           'roles.manage', 'members.invite'));
  perform private.rls_put('invitations', 'delete', private.rls_arms(array['members.invite'], null, null, null, null, true, null), null);
end $$;

-- ---------- 4. Masked views (PII roles-less reads; security_barrier, definer) ----------
create or replace view public.v_leads_masked with (security_barrier = true) as
select l.workspace_id, l.id,
       (with n as (select regexp_replace(l.full_name, '^(adv|dr|mr|ms|mrs|thiru|tmt)\.?\s+', '', 'i') as v)
        select split_part(n.v, ' ', 1) || coalesce(' ' || nullif(left(split_part(n.v, ' ', 2), 1), '') || '.', '') from n) as display_name,
       l.role_title, l.firm_name, l.city, l.district, l.status, l.score, l.first_touch_channel,
       l.first_touch_campaign, l.owner_id, l.created_at,
       case when l.email is not null then '•••@' || split_part(l.email, '@', 2) end as email_masked,
       case when l.phone is not null then '••••••' || right(l.phone, 4) end as phone_masked
  from public.leads l
 where l.deleted_at is null
   and l.workspace_id in (select authz.ws_with('leads.read', 'all'));

create or replace view public.v_contacts_masked with (security_barrier = true) as
select c.workspace_id, c.id, c.account_id,
       (with n as (select regexp_replace(c.full_name, '^(adv|dr|mr|ms|mrs|thiru|tmt)\.?\s+', '', 'i') as v)
        select split_part(n.v, ' ', 1) || coalesce(' ' || nullif(left(split_part(n.v, ' ', 2), 1), '') || '.', '') from n) as display_name,
       c.role_title, c.is_decision_maker, c.preferred_language, c.owner_id, c.created_at,
       case when c.email is not null then '•••@' || split_part(c.email, '@', 2) end as email_masked,
       case when c.phone is not null then '••••••' || right(c.phone, 4) end as phone_masked
  from public.contacts c
 where c.deleted_at is null
   and c.workspace_id in (select authz.ws_with('contacts.read', 'all'));

create or replace view public.v_conversations_masked with (security_barrier = true) as
select v.workspace_id, v.id, v.channel, v.lead_id, v.contact_id, v.assignee_id, v.status,
       v.last_inbound_at, v.last_message_at, v.created_at
  from public.conversations v
 where v.workspace_id in (select authz.ws_with('inbox.read', 'all'));

create or replace view public.v_messages_masked with (security_barrier = true) as
select m.workspace_id, m.id, m.conversation_id, m.direction, m.status, m.is_internal_note, m.sent_by, m.created_at,
       case when m.is_internal_note then null else '••••••' end as body_masked
  from public.messages m
 where m.workspace_id in (select authz.ws_with('inbox.read', 'all'));

revoke all on public.v_contacts_masked, public.v_conversations_masked, public.v_messages_masked from anon;
grant select on public.v_contacts_masked, public.v_conversations_masked, public.v_messages_masked to authenticated;

-- ---------- 5. my_grants: territory flag, module switches, plan caps ----------
create or replace function authz.my_grants(p_ws uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid()); v_role record; v_ss record; v_t record; v_perms jsonb; v_pol jsonb; v_cfg jsonb;
  v_off text[]; v_capped text[] := '{}'; v_all constant text[] := array['inbox','ai','integrations','audience','analytics','tasks','accounts','campaigns','data-health'];
begin
  if v_uid is null then return null; end if;
  select null::uuid as id, null::text as mode, null::timestamptz as expires_at into v_ss;   -- always assigned (0013 left it unset for members)
  select r.id, r.key, r.base_role into v_role
    from public.memberships m join public.roles r on r.id = m.role_id
   where m.user_id = v_uid and m.workspace_id = p_ws and m.is_active and (m.valid_until is null or m.valid_until > now());
  if v_role.id is null then
    select s.id, s.mode, s.expires_at into v_ss from public.support_sessions s
     where s.admin_id = v_uid and s.workspace_id = p_ws and s.ended_at is null and now() < s.expires_at and public.is_platform_admin()
     order by s.started_at desc limit 1;
    if v_ss.id is null then return null; end if;
    select r.id, r.key, r.base_role into v_role from public.roles r
     where r.tenant_id is null and r.key = (case v_ss.mode when 'read_write' then 'owner' else 'viewer' end);
  end if;
  select t.id, t.slug, t.status into v_t from public.workspaces w join public.tenants t on t.id = w.tenant_id where w.id = p_ws;
  select coalesce(jsonb_object_agg(g.permission_key, jsonb_build_object('scope', g.scope, 'conditions', g.conditions,
                                                                      'field_mask', to_jsonb(g.field_mask),
                                                                      'territory', (g.permission_key = 'leads.read' and g.scope = 'own'))), '{}'::jsonb)
    into v_perms from authz.grants(p_ws) g;
  select to_jsonb(p) - 'updated_by' into v_pol from public.org_admin_policies p where p.tenant_id = v_t.id;
  v_pol := coalesce(v_pol, '{}'::jsonb);

  select tc.config -> 'modules' into v_cfg from public.tenant_config tc where tc.tenant_id = v_t.id;
  select coalesce(array_agg(m order by m), '{}') into v_off from (
    select k as m from jsonb_each(case when jsonb_typeof(v_cfg) = 'object' then v_cfg else '{}'::jsonb end) e(k, v) where e.v = 'false'::jsonb
    union
    select x from unnest(v_all) x
     where jsonb_typeof(v_pol -> 'allowed_modules') = 'array' and not (v_pol -> 'allowed_modules') ? x) q;

  if (v_pol ->> 'allow_custom_roles') = 'false' then v_capped := v_capped || 'roles.manage'; end if;
  if (v_pol ->> 'allow_custom_objects') = 'false' then v_capped := v_capped || array['objects.manage', 'fields.manage']; end if;
  if (v_pol ->> 'allow_api_keys') = 'false' then v_capped := v_capped || 'api_keys.manage'; end if;
  if (v_pol ->> 'allow_webhooks') = 'false' then v_capped := v_capped || 'webhooks.manage'; end if;
  if (v_pol ->> 'max_seats') is not null
     and (select count(*) from public.memberships m join public.workspaces w on w.id = m.workspace_id
           where w.tenant_id = v_t.id and m.is_active) >= (v_pol ->> 'max_seats')::int then
    v_capped := v_capped || array['members.invite', 'members.manage'];
  end if;

  return jsonb_build_object(
    'role', jsonb_build_object('id', v_role.id, 'key', v_role.key, 'base', v_role.base_role),
    'perms', v_perms,
    'team_user_ids', (select coalesce(jsonb_agg(u), '[]'::jsonb) from authz.team_user_ids(p_ws) u),
    'attrs', authz.attr(p_ws),
    'support', case when v_ss.id is null then null
                    else jsonb_build_object('mode', v_ss.mode, 'expires_at', v_ss.expires_at) end,
    'tenant', jsonb_build_object('uuid', v_t.id, 'slug', v_t.slug, 'status', v_t.status, 'trial_ends_at', null),
    'policy', case when v_pol = '{}'::jsonb then null
                   else v_pol || jsonb_build_object('modules_off', to_jsonb(v_off), 'capped', to_jsonb(v_capped)) end);
end $$;

-- ---------- 6. Swap with parity block ----------
-- Identities = one active member per (workspace, role) already in the database. Counts are taken as that user through the real
-- authenticated role, before and after the swap. Deleted rows are excluded on both sides (v2 hides soft-deleted rows by design).
-- Deliberate deltas (documented in README 13): data role sees all activities (catalogue: activities.read all) instead of own.
do $$
declare
  v_tables constant text[] := array['leads','contacts','accounts','deals','deal_stage_history','activities','tasks','campaigns',
    'campaign_daily_metrics','audience_segments','lead_events','conversations','messages','message_templates','ga4_daily','integrations',
    'integration_field_maps','sync_runs','consent_log','ai_insights','backup_checks','backup_alert_rules','pipeline_stages','territories',
    'sales_targets','invitations','v_leads_masked'];
  v_ident record; v_t text; v_n bigint; v_before jsonb := '{}'; v_after jsonb := '{}'; v_key text; v_diffs text := ''; v_cnt int := 0;
  v_has_del boolean;
begin
  for pass in 1..2 loop
    if pass = 2 then
      perform private.rls_v2_swap();
    end if;
    for v_ident in
      select distinct on (m.workspace_id, m.role) m.user_id, m.workspace_id, m.role::text as role
        from public.memberships m
        join auth.users u on u.id = m.user_id
       where m.is_active order by m.workspace_id, m.role, m.user_id limit 60
    loop
      perform set_config('request.jwt.claims', json_build_object('sub', v_ident.user_id, 'role', 'authenticated', 'aal', 'aal1')::text, true);
      perform set_config('request.jwt.claim.sub', v_ident.user_id::text, true);
      execute 'set local role authenticated';
      foreach v_t in array v_tables loop
        v_has_del := exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = v_t and c.column_name = 'deleted_at');
        execute format('select count(*) from public.%I where workspace_id = $1 %s', v_t, case when v_has_del then 'and deleted_at is null' else '' end)
          into v_n using v_ident.workspace_id;
        v_key := v_ident.workspace_id || '|' || v_ident.role || '|' || v_t;
        if pass = 1 then v_before := v_before || jsonb_build_object(v_key, v_n);
        else v_after := v_after || jsonb_build_object(v_key, v_n); end if;
      end loop;
      execute 'reset role';
      v_cnt := v_cnt + 1;
    end loop;
  end loop;
  for v_key in select jsonb_object_keys(v_before) loop
    if (v_before ->> v_key) is distinct from (v_after ->> v_key) then
      if split_part(v_key, '|', 2) = 'data' and split_part(v_key, '|', 3) = 'activities' then
        raise notice '0016 parity: deliberate delta % old=% new=%', v_key, v_before ->> v_key, v_after ->> v_key;
      else
        v_diffs := v_diffs || format(E'\n  %s old=%s new=%s', v_key, v_before ->> v_key, v_after ->> v_key);
      end if;
    end if;
  end loop;
  if v_diffs <> '' then
    raise exception '0016 parity block FAILED (visible rows differ under v2 policies):%', v_diffs;
  end if;
  raise notice '0016 parity: % identity/table counts compared across % passes, identical', jsonb_array_length(jsonb_path_query_array(v_before, '$.*')), 2;
end $$;

-- ---------- 7. Grants ----------
revoke all on function private.rls_arms(text[], text[], text, text, text, boolean, text) from public, anon, authenticated;
revoke all on function private.rls_and(text[]) from public, anon, authenticated;
revoke all on function private.rls_put(text, text, text, text) from public, anon, authenticated;
revoke all on function private.rls_v2_swap() from public, anon, authenticated;
